export const getUpdateMemberRoleUrl = (userBusinessPlaceId: string,
    params: UpdateMemberRoleParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/business-places/members/${userBusinessPlaceId}/role?${stringifiedParams}` : `/api/business-places/members/${userBusinessPlaceId}/role`
}

